import React from "react";
import { graphql } from "gatsby";
import Item from "../components/item"
import Layout from "../components/Layout"
import BreadCrumb from "../components/BreadCrumb"
import Seo from "../components/seo"

export default function BlogPost( { data } ) {
  const post = data.markdownRemark;
  return (
    <Layout>
      <BreadCrumb links={["/","/latest"]} titles={["Home", "Latest", post.frontmatter.title ]} />

	  <Item title={ post.frontmatter.title}
	  date={ post.frontmatter.date }
          body={ post.html } />
	</Layout>
  );
}

export function Head({ data, location }) {
  const post = data.markdownRemark
  const title = post.frontmatter.title
  const description = post.excerpt || `Technical article from Wisdel.uk: ${title}.`
  const articleUrl = `https://lacdael.github.io/lacdael${post.frontmatter.slug}`
  const schema = {
    "@context": "https://schema.org",
    "@type": "TechArticle",
    "@id": `${articleUrl}#article`,
    headline: title,
    description,
    url: articleUrl,
    datePublished: post.frontmatter.date,
    dateModified: post.frontmatter.date,
    inLanguage: "en-GB",
    author: {
      "@type": "Person",
      name: "Christian Lacdael",
      url: "https://lacdael.github.io/lacdael/contact/",
    },
    publisher: {
      "@type": "Organization",
      name: "Wisdel.uk",
      url: "https://lacdael.github.io/lacdael/",
    },
    isPartOf: { "@id": "https://lacdael.github.io/lacdael/#website" },
  }

  return (
    <Seo
      title={title}
      description={description}
      date={post.frontmatter.date}
      image="/banner.jpg"
      imageAlt={`${title} - Wisdel.uk`}
      imageWidth={1200}
      imageHeight={630}
      what="article"
      schemaMarkup={schema}
      pathname={location.pathname}
    />
  )
}

export const query = graphql`
  query ($id: String!) {
    markdownRemark(id: { eq: $id }) {
      html
      excerpt(pruneLength: 160)
      frontmatter {
        title
        date
	slug
      }
    }
  }
`;
